const pd=s=>{const m=/^(\d{4})-(\d{2})-(\d{2})$/.exec(s||'');return m?new Date(+m[1],m[2]-1,+m[3]):null};
const iso=d=>d?d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0'):'';
const addD=(d,n)=>{const x=new Date(d);x.setDate(x.getDate()+n);return x};
const addBD=(d,n)=>{const x=new Date(d);let k=0;const step=n<0?-1:1;while(k<Math.abs(n)){x.setDate(x.getDate()+step);if(isBiz(x))k++}return x};
const fmt=s=>{const d=pd(s);return d?d.toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'}):''};
const fmtS=s=>{const d=pd(s);return d?d.toLocaleDateString('en-US',{weekday:'short',month:'short',day:'numeric'}):''};
const fmtN=s=>{const d=pd(s);return d?String(d.getMonth()+1).padStart(2,'0')+'/'+String(d.getDate()).padStart(2,'0')+'/'+d.getFullYear():''};
const fmtX=s=>{const d=pd(s);return d?(d.getMonth()+1)+'/'+d.getDate()+'/'+String(d.getFullYear()).slice(2):''};
