const cDeadRaw=(tx,c)=>{if(!c||c.days===''||c.days==null)return c&&c.k==='coe'&&c.date?c.date:'';const n=parseInt(c.days,10);if(isNaN(n))return '';let base;if(c.from==='coe'&&c.k!=='coe'){const ce=(tx.cont||[]).find(x=>x.k==='coe');base=pd(ce?cdate(tx,ce):'');if(!base)return '';return iso(c.biz?addBD(base,-n):addD(base,-n))}base=pd(day0(tx));if(!base)return '';return iso(c.biz?addBD(base,n):addD(base,n))};
const cDead=(tx,c)=>{const r=cDeadRaw(tx,c);if(!r||tx.f.roll==='no')return r;return iso(rollBiz(pd(r)))};
const cdateRaw=(tx,c)=>{if(!c)return '';if(c.k==='coe'&&c.coeMode==='days')return cDeadRaw(tx,c);if(c.date)return c.date;return cDeadRaw(tx,c)};
const cLinked=(tx,c)=>{if(!c||c.k==='coe'||c.unlink)return [];const d=cDead(tx,c);if(!d)return [];return (tx.cont||[]).filter(x=>x!==c&&x.k!=='coe'&&!x.waived&&!x.unlink&&cDead(tx,x)===d)};
const cdate=(tx,c)=>{const r=cdateRaw(tx,c);if(!r||!c||c.date||tx.f.roll==='no')return r;return iso(rollBiz(pd(r)))};
const rolled=(tx,c)=>{const r=cdateRaw(tx,c);return r&&r!==cdate(tx,c)};
const coeOf=tx=>cdate(tx,(tx.cont||[]).find(c=>c.k==='coe'));
const LSBASE={LIST:'list_date',FIRST:'first_look',LIVE:'live_date',EXP:'expiration',PHOTOS:'photos_date'};
function baseDate(tx,code){if(code==='ACC')return day0(tx);if(LSBASE[code])return tx.f[LSBASE[code]]||'';const c=(tx.cont||[]).find(x=>x.k&&x.k.toUpperCase()===code);return c?cdate(tx,c):''}
function linkCont(tx,i){if(!i.ms||!i.drv||(parseInt(i.days,10)||0)!==0)return;const c=(tx.cont||[]).find(x=>x.k&&x.k.toUpperCase()===i.drv);if(c)c.removed=!!i.done}
function itemDue(tx,i,dep=0){if(!i.drv||i.drv==='DATE')return i.due||'';let base='';
 if(i.drv.startsWith('T:')){const t=tx.checklist.find(x=>x.id===i.drv.slice(2));base=t?(t.done?(t.doneAt||''):(dep<8?itemDue(tx,t,dep+1):'')):''}else base=baseDate(tx,i.drv);
 const d=pd(base);const n=parseInt(i.days||0,10)||0;return d?iso(i.biz?addBD(d,n):addD(d,n)):''}

/* names */
const short=n=>{n=String(n||'').trim().split(/\s*(?:&|,|\band\b)\s*/i)[0];const p=n.split(/\s+/).filter(Boolean);if(!p.length)return '';return p[0]+(p.length>1?' '+p[p.length-1][0]+'.':'')};
const lastNames=s=>String(s||'').split(/\s*(?:&|\band\b|\n|;)\s*/i).map(x=>x.trim()).filter(Boolean).map(x=>{if(/\b(llc|inc|trust|trustee|estate|corp|group|lp)\b/i.test(x))return x;const p=x.split(/\s+/);return p[p.length-1]});
const joinL=a=>{a=[...new Set(a)];return a.length>2?a.slice(0,-1).join(', ')+' & '+a[a.length-1]:a.join(' & ')};
function titleOf(t){const f=effF(t);const L=kindOf(t)==='listing';const ag=short(!L&&f.side==='Buyer'?(f.ba_name||f.la_name):(f.la_name||f.ba_name));
 const cut=x=>x&&x.length>42?x.slice(0,40).replace(/[ ,&]+\S*$/,'')+'…':x;
 const sl=cut(joinL(lastNames(f.sellers))),bl=cut(joinL(lastNames(f.buyers)));
 if(L)return [ag,sl].filter(Boolean).join(' | ').toUpperCase();
 const side=f.side?'('+f.side[0]+')':'';const parties=(sl||bl)?`${sl||'?'} TO ${bl||'?'}`:'';
 return [[ag,ag?side:''].filter(Boolean).join(' '),parties].filter(Boolean).join(' | ').toUpperCase()}

const cDaysLbl=c=>c.k==='coe'||c.days===''||c.days==null?'':c.from==='coe'?'COE −'+Math.abs(c.days):String(c.days)+(c.biz?' biz':'');
const isContTask=(tx,i)=>!!(i.drv&&(tx.cont||[]).some(c=>c.k&&c.k.toUpperCase()===i.drv));
function timeline(tx){const rows=[];
 (tx.cont||[]).forEach(c=>{const d=cdate(tx,c);if(d||c.waived)rows.push({d,label:c.label,days:cDaysLbl(c),st:c.waived?'Waived':c.removed?'Completed':''})});
 (tx.checklist||[]).filter(i=>i.ms&&!isContTask(tx,i)).forEach(i=>{const d=i.done?(i.doneAt||itemDue(tx,i)):itemDue(tx,i);if(d)rows.push({d,label:i.text,st:i.done?'Completed '+fmtX(i.doneAt):''})});
 if(kindOf(tx)!=='listing'&&tx.f.acceptance)rows.push({d:tx.f.acceptance,label:'Acceptance date',st:''});
 return rows.sort((a,b)=>(a.d||'9')<(b.d||'9')?-1:1)}
const asstsOf=c=>!c?[]:Array.isArray(c.assts)?c.assts.filter(a=>a&&(a.name||a.email||a.phone)):(c.asst_name||c.asst_email||c.asst_phone?[{name:c.asst_name||'',email:c.asst_email||'',phone:c.asst_phone||''}]:[]);
function effF(tx){const f=tx.f||{};const ex=(tx.extra||[]);const add=(role,nk,ek,pk)=>{const xs=ex.filter(x=>x.role===role).map(x=>S.contacts.find(c=>c.id===x.cid)).filter(Boolean);if(!xs.length)return null;return {[nk]:[f[nk]].concat(xs.map(c=>c.name)).filter(Boolean).join(' & '),[ek]:[f[ek]].concat(xs.map(c=>c.email)).filter(Boolean).join(', ')}};const a=add('Buyer','buyers','buyer_email'),b=add('Seller','sellers','seller_email');return a||b?Object.assign({},f,a||{},b||{}):f}
function mergeMap(tx){const f=effF(tx);const m={};for(const k in f)m[k]=f[k];
 m.compliance_email=f.doc_email||'';m.contract_terms=[termLines(f),f.special].filter(x=>String(x||'').trim()).join('\n\n');m.oth_compliance_email=f.oth_doc_email||'';
 try{Object.keys(PARTY).forEach(p=>{const c=S.contacts.find(x=>x.id===f[p+'_cid']);if(c&&c.team_email)m[p+'_team_email']=c.team_email;const A=asstsOf(c);if(!A.length&&!(c&&c.team_email))return;const em=[f[p+'_asst_email'],c&&c.team_email].concat(A.map(a=>a.email)).filter(Boolean).filter((x,i,a)=>a.findIndex(y=>y.toLowerCase()===x.toLowerCase())===i);m[p+'_asst_email']=em.join(', ');m[p+'_asst_name']=A.map(a=>a.name).filter(Boolean).join(' & ');m[p+'_asst_phone']=A.map(a=>a.phone).filter(Boolean).join(', ')})}catch(e){}
 ['price','emd_amount','loan_amount','down_payment','seller_credit','buyer_credit','repair_credit','hw_amount','list_price'].forEach(k=>{if(f[k])m[k]=money(f[k])});
 ['acceptance','offer_date','list_date','live_date','expiration','photos_date','first_look'].forEach(k=>{if(f[k])m[k]=fmt(f[k])});
 (tx.cont||[]).forEach(c=>{const k=ckey(c);if(k){const d=cdate(tx,c);m[k+'_date']=c.waived?'Waived':fmt(d);m[k+'_day']=c.waived?'':fmtS(d);m[k+'_short']=c.waived?'Waived':fmtX(d)}});
 m.full_address=[f.address,f.city].filter(Boolean).join(', ');m.state=f.state||'CA';m.seller_last=joinL(lastNames(f.sellers));m.buyer_last=joinL(lastNames(f.buyers));
 const first=n=>joinL(String(n||'').split(/\s*(?:&|\band\b|\n|;)\s*/i).map(x=>x.trim().split(/\s+/)[0]).filter(Boolean));
 m.buyer_first=first(f.buyers);m.seller_first=first(f.sellers);m.esc_first=first(f.esc_officer);m.lender_first=first(f.lender_officer);['ba','la','bca','lca'].forEach(p=>m[p+'_first']=first(f[p+'_name']));
 {const FK={ba:'ba_first',la:'la_first',bca:'bca_first',lca:'lca_first',esc:'esc_first',lender:'lender_first',buyer:'buyer_first',seller:'seller_first'};Object.keys(FK).forEach(p=>{const c=S.contacts.find(x=>x.id===f[p+'_cid']);if(c&&c.nickname)m[FK[p]]=c.nickname})}
 const L=kindOf(tx)==='listing',rs=L||f.side==='Seller';const R=rs?'la':'ba',O=rs?'ba':'la',RC=rs?'lca':'bca',OC=rs?'bca':'lca',OT=rs?'btc':'ltc';
 m.rep_agent_name=f[R+'_name'];m.rep_agent_first=m[R+'_first'];m.rep_agent_email=f[R+'_email'];m.rep_coagent_name=f[RC+'_name'];m.rep_coagent_first=m[RC+'_first'];m.rep_coagent_email=f[RC+'_email'];
 m.oth_agent_name=f[O+'_name'];m.oth_agent_first=m[O+'_first'];m.oth_agent_email=f[O+'_email'];m.oth_coagent_first=m[OC+'_first'];m.oth_coagent_email=f[OC+'_email'];m.oth_tc_name=f[OT+'_name'];m.oth_tc_email=f[OT+'_email'];m.oth_tc_phone=f[OT+'_phone'];
 m.rep_client_first=rs?m.seller_first:m.buyer_first;m.rep_client_last=rs?m.seller_last:m.buyer_last;m.rep_client_email=rs?f.seller_email:f.buyer_email;
 m.phase_name=phaseOf(tx).name;m.timeline=timeline(tx).map(r=>`${r.d?fmtX(r.d):'-'} - ${r.label}${r.st?' ('+r.st+')':''}`).join('\n');m.today=fmt(today());return m}
const merge=(t,m)=>String(t||'').replace(/\{\{\s*([a-z0-9_]+)\s*\}\}/gi,(a,k)=>(m[k]!==undefined&&m[k]!=='')?m[k]:a);

function due(dl){if(dl==null)return '';if(dl<0)return `<span class="pill over">${-dl}d overdue</span>`;if(dl===0)return '<span class="pill over">Today</span>';if(dl<=3)return `<span class="pill soon">in ${dl}d</span>`;return `<span class="pill">in ${dl}d</span>`}
function deadlines(t){const out=[];const f=t.f||{};
 if(kindOf(t)==='listing'){if(f.live_date&&['Incomplete','First Look'].includes(f.status))out.push({label:'Go live',date:f.live_date,tx:t});if(f.expiration&&f.status==='Active')out.push({label:'Listing expires',date:f.expiration,tx:t})}
 else (t.cont||[]).forEach(c=>{if(c.waived||c.removed)return;const d=cdate(t,c);if(d)out.push({label:c.label,date:d,tx:t})});
 (t.checklist||[]).forEach(i=>{if(i.done)return;const d=itemDue(t,i);if(d)out.push({label:i.text,date:d,tx:t,who:i.who})});return out.sort((a,b)=>a.date<b.date?-1:1)}
const isOpen=t=>OPEN[kindOf(t)].includes(t.f.status);
const normTx=o=>{o.kind=o.kind||'transaction';o.f=o.f||{};if(!Array.isArray(o.emails))o.emails=[];if(Array.isArray(o.notes)&&!o.noteOrd)o.notes.sort((a,b)=>(b.at||0)-(a.at||0));const f=o.f;const L=o.kind==='listing';
 const LSMAP={'Pre-listing':'Incomplete','Coming soon':'First Look','Active':'Active','Pending':'Pending','Sold':'Closed','Withdrawn':'Canceled','Expired':'Expired'};
 if(!(L?LS_STATUS:TX_STATUS).includes(f.status))f.status=L?(LSMAP[f.phase]||'Incomplete'):({'Closed':'Closed','Cancelled':'Canceled'}[f.phase]||'Open');
 if(OLDPH.includes(f.phase))f.phase='';if(f.side==='Both')f.side='Dual';
 o.cont=o.cont||(L?[]:DEFAULT_CONT());o.checklist=(o.checklist||[]).map(i=>{if(!i.drv)i.drv='DATE';return i});o.notes=o.notes||[];return o};

/* ---------- storage ---------- */
function upsertLocal(kind,obj){const a=S[kind];const i=a.findIndex(x=>x.id===obj.id);if(i<0)a.push(obj);else a[i]=obj}
function body(obj){const o={};for(const k in obj){if(k!=='id'&&k[0]!=='_')o[k]=obj[k]}return clone(o)}
function queued(key,fn){const run=async()=>{try{return await fn()}catch(e){if(e&&e.code==='unavailable'){await new Promise(r=>setTimeout(r,400+Math.random()*600));return fn()}throw e}};
 const p=(chains[key]||Promise.resolve()).then(run,run);chains[key]=p.catch(()=>{});return p}
function dbErr(e){const c=e&&e.code;if(c==='quota_exceeded')toast('Storage is full. Delete old records to make room.');else if(c==='invalid_argument')toast('Couldn\'t save: '+(/size|large|big|limit/i.test((e&&e.message)||'')?'it is too large. Use smaller pictures.':((e&&e.message)||'the data was not accepted')));else toast('Couldn\'t save. Check your connection.');setSaving('Not saved')}
const ARCOL='archive';const isArchTx=t=>!!(t&&(t.vault||(t.f&&t.f.status==='Archived')));
let _arP=null;function loadArchive(){if(_arP)return _arP;if(!db){S.arLoaded=true;return Promise.resolve()}
 _arP=new Promise(res=>{let first=true;db.collection(ARCOL).onSnapshot(snap=>{const arr=snap.docs.map(d=>{const o=normTx(Object.assign(clone(d.data()),{id:d.id}));o._col=ARCOL;if(dirty.has(o.id)){const loc=S.tx.find(x=>x.id===o.id);if(loc)return loc}return o});
  const act=S.tx.filter(t=>t._col!==ARCOL);const actIds=new Set(act.map(t=>t.id));S.tx=act.concat(arr.filter(o=>!actIds.has(o.id)));S.arLoaded=true;
  if(first){first=false;res()}if(!S.importing){if(S.view==='archive')renderArchive();else onData('tx')}},e=>{S.arLoaded=true;if(first){first=false;res()}})});return _arP}
let _migBusy=false;async function migrateArchive(){if(_migBusy||!db||S.importing)return;const mv=S.tx.filter(t=>t._col===COLS.tx&&isArchTx(t)&&!dirty.has(t.id));if(!mv.length)return;_migBusy=true;
 try{for(let i=0;i<mv.length;i+=10){await Promise.all(mv.slice(i,i+10).map(t=>save('tx',t).catch(()=>{})))}}finally{_migBusy=false}}
async function save(kind,obj){obj.updatedAt=Date.now();upsertLocal(kind,obj);if(!db)return;const b=body(obj);
 if(kind==='tx'){const col=isArchTx(obj)?ARCOL:COLS.tx;const old=obj._col;obj._col=col;await queued('tx/'+obj.id,async()=>{await db.collection(col).doc(obj.id).set(b);if(old&&old!==col){try{await db.collection(old).doc(obj.id).delete()}catch(e){}}});return}
 await queued(kind+'/'+obj.id,()=>db.collection(COLS[kind]).doc(obj.id).set(b))}
async function remove(kind,id){if(kind==='contacts'&&BOOKS.some(b=>(b.items||[]).some(c=>c.id===id))){S.contacts=S.contacts.filter(x=>x.id!==id);if(db)await queued('contacts/'+id,()=>db.collection('contacts').doc(id).set({deleted:true}));return}const was=kind==='tx'?S.tx.find(x=>x.id===id):null;S[kind]=S[kind].filter(x=>x.id!==id);if(!db)return;await queued(kind+'/'+id,()=>db.collection(kind==='tx'&&was&&was._col?was._col:COLS[kind]).doc(id).delete())}
function setSaving(t){const el=$('#saving');if(el)el.textContent=t}
function touch(tx,fast){tx._v=(tx._v||0)+1;dirty.add(tx.id);clearTimeout(timers[tx.id]);setSaving(db?'Saving…':'');timers[tx.id]=setTimeout(()=>flush(tx.id),fast?150:700)}
async function flush(id){clearTimeout(timers[id]);delete timers[id];const tx=getTx(id);if(!tx){dirty.delete(id);return}const v=tx._v;
 try{await save('tx',tx);if(tx._v===v)dirty.delete(id);if(!Object.keys(timers).length)setSaving(db?'Saved':'')}catch(e){dbErr(e)}}
function flushAll(){Object.keys(timers).forEach(flush)}

/* ---------- ui helpers ---------- */
let toastT;function toast(m){const t=$('#toast');t.textContent=m;t.classList.remove('hidden');clearTimeout(toastT);toastT=setTimeout(()=>t.classList.add('hidden'),2600)}
function askBox(title,fields,cb){const m=aiModal(`<h3 style="margin-top:0">${esc(title)}</h3>${fields.map(([k,l,v])=>`<label class="f">${esc(l)}<input data-ask="${k}" value="${esc(v||'')}"></label>`).join('')}<div class="row end" style="margin-top:10px"><button class="btn" data-m="no">Cancel</button><button class="btn pri" id="askOk">OK</button></div>`);const bx=m.querySelector('.mbox');bx.style.maxWidth='440px';const go=()=>{const v={};bx.querySelectorAll('[data-ask]').forEach(i=>v[i.dataset.ask]=i.value.trim());m.classList.add('hidden');cb(v)};bx.querySelector('#askOk').onclick=go;bx.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();go()}});setTimeout(()=>{const i=bx.querySelector('[data-ask]');i&&(i.focus(),i.select())},30)}
function confirmBox(msg,ok,onOk){const m=$('#modal');m.innerHTML=`<div class="mbox"><p style="margin-top:0">${msg}</p><div class="row end"><button class="btn" data-m="no">Cancel</button><button class="btn pri" data-m="ok">${ok}</button></div></div>`;m.classList.remove('hidden');
 m.onclick=e=>{const b=e.target.dataset.m;if(b||e.target===m){m.classList.add('hidden');if(b==='ok')onOk()}}}
function bodyHTML(t){const L=String(t).split('\n');let h='',tb=[];const flush=()=>{if(!tb.length)return;h+='<table style="border-collapse:collapse;margin:6px 0">'+tb.map((r,i)=>'<tr>'+r.map(c=>`<${i?'td':'th'} style="border:1px solid #999;padding:4px 10px;text-align:left${i?'':';background:#eee'}">${esc(c.trim())}</${i?'td':'th'}>`).join('')+'</tr>').join('')+'</table>';tb=[]};
 L.forEach(l=>{if(/\s\|\s/.test(l))tb.push(l.split(/\s\|\s/));else{flush();h+=esc(l)+'<br>'}});flush();return '<div style="font-family:Arial,sans-serif;font-size:14px">'+h+'</div>'}
async function richCopy(t){try{if(window.ClipboardItem){const h=isHTML(t)?'<div style="font-family:Arial,sans-serif;font-size:14px">'+t+'</div>':bodyHTML(t);await navigator.clipboard.write([new ClipboardItem({'text/html':new Blob([h],{type:'text/html'}),'text/plain':new Blob([toText(t)],{type:'text/plain'})})]);toast('Body copied');return}}catch(e){}copy(t,'Body')}
async function copy(text,label){try{await navigator.clipboard.writeText(text);toast((label||'Text')+' copied')}catch(e){toast('Copy was blocked. Select the text and copy it manually.')}}
const editing=()=>{const a=document.activeElement;return a&&app.contains(a)&&/INPUT|TEXTAREA|SELECT/.test(a.tagName)};

function top(){const nv=(v,k,l)=>{const on=v==='list'?(S.view==='list'||S.view==='detail')&&S.kind===k:v==='tasks'?S.view==='tasks'&&S.tk.kind===k:v==='contacts'?S.view==='contacts'&&(S.cTab==='clients'?'clients':'assoc')===(k||'assoc'):S.view===v;return `<button data-act="nav" data-v="${v}" ${k?`data-k="${k}"`:''} class="${on?'on':''}" ${v==='chat'?'id="navChat"':''}>${l}${v==='chat'?chatBadge():''}</button>`};
 return `<header class="top"><div class="brand"><svg class="blogo" width="22" height="22" viewBox="0 0 64 64" aria-hidden="true"><rect width="64" height="64" rx="14" fill="#101828"/><path d="M12 22 a4 4 0 0 1 4-4 h10 l5 5 h17 a4 4 0 0 1 4 4 v19 a4 4 0 0 1 -4 4 h-32 a4 4 0 0 1 -4-4 z" fill="#B42318"/><path d="M23 35 L29 41 L41 29" fill="none" stroke="#fff" stroke-width="5" stroke-linecap="round" stroke-linejoin="round"/></svg>TC Desk</div><nav class="main">${nv('list','listing','Listings')}${nv('tasks','listing','Listing tasks')}${nv('list','transaction','Transactions')}${nv('tasks','transaction','Transaction tasks')}${nv('chat','','Chat')}${nv('archive','','Archive')}${nv('contacts','assoc','Associates')}${nv('contacts','clients','Buyers & Sellers')}${nv('templates','','Templates')}</nav><div class="grow"></div><span id="saving" class="mut small"></span></header>`+
 (S.offline?'<div class="banner">Saving is off in this view. Open this page on claude.ai while signed in to keep your data.</div>':'')+
 (S.slow?'<div class="banner">Your data can\'t be reached yet. What you see may be out of date.</div>':'')+
 (S.err?`<div class="banner">Couldn't load your data (${esc(S.err)}). Reload the page to try again.</div>`:'')+impBanner()}
let _rk='';function render(){const k=S.view+'|'+(S.view==='detail'?S.txId:'')+'|'+(S.view==='tasks'?S.tk.kind:S.kind),y=window.scrollY;if(S.view==='detail')renderDetail();else if(S.view==='templates')renderTemplates();else if(S.view==='contacts')renderContacts();else if(S.view==='tasks')renderTasks();else if(S.view==='archive')renderArchive();else if(S.view==='chat')renderChat();else renderList();if(k===_rk&&y)window.scrollTo(0,y);_rk=k;const nv=document.querySelector('nav.main'),on=nv&&nv.querySelector('.on');if(on&&nv.scrollWidth>nv.clientWidth)nv.scrollLeft=on.offsetLeft-nv.clientWidth/2+on.offsetWidth/2}

/* ---------- cards & list ---------- */
function ckStats(tx){const c=tx.checklist||[];const d=c.filter(i=>i.done).length,t=c.length;return {d,t,p:t?Math.round(d/t*100):0}}
function card(t,click){const f=t.f;const ph=phaseOf(t);const L=kindOf(t)==='listing';const s=ckStats(t);
 const ttl=titleOf(t)||(f.address?'':'NEW '+(L?'LISTING':'TRANSACTION'));
 const addr=[f.address,f.city,f.city||f.state?(f.state||'CA'):'',f.zip].filter(Boolean).join(' ').toUpperCase();
 let rl,rd='';if(L){if(['Incomplete','First Look'].includes(f.status)&&f.live_date){rl='LIVE ON';rd=f.live_date}else if(f.status==='Incomplete'&&f.list_date){rl='STARTED ON';rd=f.list_date}else if(f.status==='Active'&&f.expiration){rl='EXPIRES';rd=f.expiration}else rl=(f.status||'').toUpperCase()}
 else{if(OPEN.transaction.includes(f.status)||f.status==='Compliance'||f.status==='Awaiting Payment'){rl='CLOSING';rd=coeOf(t)}else rl=(f.status||'').toUpperCase()}
 const nx=deadlines(t)[0];const over=deadlines(t).filter(d=>daysTo(d.date)<0).length;
 return `<div class="tcard${click?' click':''}" ${click?`data-act="open-tx" data-id="${t.id}"`:''} style="background:${ph.bg};color:${ph.fg}">
 <div class="own">${f.owner?'Owned by '+esc(f.owner):'Unassigned'}${f.status&&rl!==f.status.toUpperCase()?' · '+esc(f.status):''}</div>
 <div class="tr"><span class="ttl">${esc(ttl||addr||'Untitled')}</span><span>${esc(rl)}</span></div>
 <div class="tr"><span>${ttl?esc(addr):''}</span><span>${rd?fmtN(rd):''}</span></div>
 ${s.t?`<div class="bar2"><i style="width:${s.p}%;background:${ph.bg};opacity:1;filter:brightness(1.15)"></i><span>${s.p}% Complete (${s.t-s.d} task${s.t-s.d===1?'':'s'} to do)</span></div>`:''}
 <div class="foot"><span>${nx&&isOpen(t)?`Next: ${esc(nx.label.length>48?nx.label.slice(0,46)+'…':nx.label)} · ${fmtS(nx.date)}${over?` · <b>${over} overdue</b>`:''}`:''}</span><i>${esc(ph.name)}</i></div></div>`}
const ofKind=()=>S.tx.filter(t=>kindOf(t)===S.kind);
function listItems(){const k=S.kind,q=S.q.toLowerCase();
 const arr=ofKind().filter(t=>{const f=t.f;if(t.vault||f.status==='Archived'||!S.st[k].includes(f.status))return false;if(k==='transaction'&&!S.rep.includes(f.side||'Buyer'))return false;
  if(S.mem.length&&!S.mem.includes(f.owner||''))return false;if(S.phHide[k].includes(phaseOf(t).id))return false;if(q&&!JSON.stringify(f).toLowerCase().includes(q))return false;return true});
 const [o,dir]=S.sort[k];const key={entry:t=>t.createdAt||0,acc:t=>t.f.acceptance||'9',coe:t=>coeOf(t)||'9',addr:t=>(t.f.address||'').toLowerCase(),live:t=>t.f.live_date||'9',exp:t=>t.f.expiration||'9',agent:t=>titleOf(t)}[o]||(t=>t.createdAt||0);
 return arr.sort((a,b)=>{const x=key(a),y=key(b);return (x<y?-1:x>y?1:0)*(dir==='asc'?1:-1)})}
function cardsHTML(){if(!S.loaded)return '<p class="mut">Loading…</p>';const arr=listItems();
 if(!arr.length)return `<div class="card mut" style="text-align:center;padding:30px">${ofKind().length?'Nothing matches these filters.':`No ${KLABEL[S.kind][1]}s yet. Click "New ${KLABEL[S.kind][1]}" to start one.`}</div>`;return arr.map(t=>card(t,true)).join('')}
function phChips(){const k=S.kind;return phasesFor(k).concat([NOPH]).map(p=>`<button class="phchip ${S.phHide[k].includes(p.id)?'off':''}" style="background:${p.bg};color:${p.fg}" data-act="phf" data-v="${esc(p.id)}">${S.phHide[k].includes(p.id)?'':'✓ '}${esc(p.name)}</button>`).join('')}
function filters(){const k=S.kind;const all=ofKind().filter(t=>!t.vault&&t.f.status!=='Archived');const cnt=(fn)=>all.filter(fn).length;
 const cb=(grp,v,l,on,n)=>`<label><input type="checkbox" data-flt="${grp}" value="${esc(v)}" ${on?'checked':''}>${esc(l)}${n!=null?` <b>${n}</b>`:''}</label>`;
 const ord=k==='listing'?[['entry','Entry date'],['live','Live date'],['exp','Expiration'],['addr','Address'],['agent','Agent']]:[['entry','Entry date'],['acc','Acceptance date'],['coe','Close date'],['addr','Address'],['agent','Agent']];
 return `<h4>Status</h4>${(k==='listing'?LS_STATUS:TX_STATUS).filter(s=>s!=='Archived').map(s=>cb('st',s,s,S.st[k].includes(s),cnt(t=>t.f.status===s))).join('')}`+
 (k==='transaction'?`<h4>Representation</h4>${['Buyer','Seller','Dual'].map(r=>cb('rep',r,r,S.rep.includes(r))).join('')}`:'')+
 (S.members.length?`<h4>Owned by</h4>${S.members.map(m=>cb('mem',m.name,m.name,S.mem.includes(m.name))).join('')}${cb('mem','','Unassigned',S.mem.includes(''))}<div class="hint">None checked shows everyone.</div>`:'')+
 `<h4>Order by</h4>${ord.map(([v,l])=>`<label><input type="radio" name="ord" data-flt="ord" value="${v}" ${S.sort[k][0]===v?'checked':''}>${l}</label>`).join('')}
 <h4>Direction</h4>${[['asc','Ascending'],['desc','Descending']].map(([v,l])=>`<label><input type="radio" name="dir" data-flt="dir" value="${v}" ${S.sort[k][1]===v?'checked':''}>${l}</label>`).join('')}`}
function upcoming(){const items=[].concat(...ofKind().filter(isOpen).map(deadlines)).filter(d=>{const n=daysTo(d.date);return n!=null&&n<=7}).sort((a,b)=>a.date<b.date?-1:1).slice(0,15);
 if(!items.length)return '<p class="mut small" style="margin:0">Nothing due in the next 7 days.</p>';
 return items.map(d=>`<div class="upi" data-act="open-tx" data-id="${d.tx.id}"><div><b>${esc(d.label)}</b><div class="mut small">${esc(d.tx.f.address||'Untitled')}${d.who?' · '+esc(d.who):''}</div></div><div style="text-align:right" class="small">${fmtS(d.date)}<br>${due(daysTo(d.date))}</div></div>`).join('')}
function saveFilters(){const v=JSON.stringify({st:S.st,sort:S.sort});if(v===S._lfLast)return;S._lfLast=v;LS.lf=JSON.parse(v);saveLS();clearTimeout(S._lfT);S._lfT=setTimeout(()=>{if(db&&S.uid){try{db.collection('data/users/'+S.uid).doc('prefs').set(Object.assign({},S.uprefs||{},{lf:JSON.parse(v)})).catch(()=>{})}catch(e){}}},800)}
function refreshList(){saveFilters();const c=$('#txBody'),f=$('#filt'),u=$('#upBody'),p=$('#phChips'),n=$('#lcnt');if(c)c.innerHTML=cardsHTML();if(f)f.innerHTML=filters();if(u)u.innerHTML=upcoming();if(p)p.innerHTML=phChips();if(n)n.textContent=S.loaded?listItems().length:''}
function renderList(){app.innerHTML=top()+`<div class="wrap wide"><div class="row between"><h1>${KLABEL[S.kind][0]} <span class="cnt" id="lcnt"></span></h1><span class="row" style="gap:6px"><button class="btn pri" data-act="new-tx">+ New ${KLABEL[S.kind][1]}</button></span></div>
 <div class="toolbar"><div class="qwrap"><input id="q" style="max-width:none" placeholder="Search ${KLABEL[S.kind][0].toLowerCase()}…" value="${esc(S.q)}"><button class="qx ${S.q?'':'hidden'}" data-act="q-clear" title="Clear search">✕</button></div></div>
 <div class="card phbox"><div class="row between" style="margin-bottom:8px"><b class="small">Phase filter / color</b><span><button class="linkbtn small" data-act="phf-all">All</button> · <button class="linkbtn small" data-act="phf-none">None</button></span></div><div class="fchips" id="phChips"></div></div>
 <div class="layout3"><div class="actcol"><div class="card acts"><h4>Actions</h4><button data-act="new-tx">+ Add new</button><button data-act="nav" data-v="tasks" data-k="${S.kind}">🕒 Itinerary</button><button data-act="today-tasks">Today's tasks</button><button data-act="list-export">Export ${KLABEL[S.kind][0].toLowerCase()}</button></div></div><div class="cards" id="txBody"></div><div class="sidecol"><div class="card filt" id="filt"></div></div></div></div>`;refreshList()}

/* ---------- detail ---------- */
function phBar(tx){const k=kindOf(tx);const f=tx.f;let link='';
 if(k==='listing')link=f.tx_id&&getTx(f.tx_id)?`<button class="btn sm" data-act="open-tx" data-id="${f.tx_id}">View transaction</button>`:`<button class="btn sm" data-act="ls-convert">Open escrow from listing</button>`;
 else if(tx.listingId&&getTx(tx.listingId))link=`<button class="btn sm" data-act="open-tx" data-id="${tx.listingId}">View listing</button>`;
 const cur=phaseOf(tx);return `<div class="phpick"><span class="mut small">Phase</span><button class="phcur" data-act="ph-open" style="background:${esc(cur.bg||'#777')};color:${esc(cur.fg||'#fff')}">${esc(cur.name||'Not Specified')} ▾</button><div class="phpop hidden" id="phPop">${phasesFor(k).map(p=>`<button class="phopt ${p.id===f.phase?'on':''}" data-act="ph-set" data-id="${p.id}" style="background:${esc(p.bg)};color:${esc(p.fg)}">${esc(p.name)||'&nbsp;'}</button>`).join('')}<button class="phun" data-act="ph-set" data-id="">✕ Unassign current phase</button></div></div>
 <label>Status <select data-f="status">${(k==='listing'?LS_STATUS:TX_STATUS).map(s=>`<option ${s===f.status?'selected':''}>${s}</option>`).join('')}</select></label><div class="grow"></div>${link}${downloads?'<button class="btn sm" data-act="sum-pdf" title="Download the summary as a PDF">⬇ PDF</button>':''}<button class="btn sm" data-act="tx-archive">${f.status==='Archived'||tx.vault?'Unarchive':'Archive'}</button><button class="btn sm" data-act="copy-tx">Copy</button><button class="btn sm danger" data-act="del-tx">Delete</button>`}
const fullAddr=tx=>{const f=tx.f||{};return [f.address,[f.city,[f.city||f.state?(f.state||'CA'):'',f.zip].filter(Boolean).join(' ')].filter(Boolean).join(', ')].filter(Boolean).join(', ')};
function dealNav(tx){let ids;try{ids=listItems().map(t=>t.id)}catch(e){ids=[]}if(!ids.includes(tx.id))ids=S.tx.filter(t=>kindOf(t)===kindOf(tx)&&isOpen(t)).map(t=>t.id);const i=ids.indexOf(tx.id);return {i,n:ids.length,prev:i>0?ids[i-1]:null,next:i>=0&&i<ids.length-1?ids[i+1]:null}}
function goDeal(id,dir){if(!id)return;S._sumMarked=null;flushAll();S.txId=id;S.noteEdit='';render();navSync();window.scrollTo(0,0);if(dir){const w=$('.wrap');if(w){w.classList.add(dir<0?'slin-l':'slin-r');setTimeout(()=>w.classList.remove('slin-l','slin-r'),300)}}}
function gotoResults(q){q=q.trim().toLowerCase();const K=S.kind;if(!q)return [];return S.tx.filter(t=>kindOf(t)===K&&(String(t.f.address||'')+' '+(t.f.city||'')+' '+titleOf(t)+' '+(t.f.mls||'')+' '+(t.f.esc_number||'')).toLowerCase().includes(q)).sort((a,b)=>(isOpen(b)?1:0)-(isOpen(a)?1:0)).slice(0,10)}
function renderDetail(){const tx=getTx();if(!tx){S.view='list';return renderList()}const k=kindOf(tx);S.kind=k;if(!TABS[k].find(t=>t[0]===S.tab))S.tab='terms';
 const nav=dealNav(tx);app.innerHTML=top()+`<div class="wrap"><div class="dtop"><div class="dnav"><button class="btn ghost sm" data-act="back">← All ${KLABEL[k][0].toLowerCase()}</button><span class="grow"></span>
 <div class="goto"><button class="btn sm" data-act="deal-go" data-id="${nav.prev||''}" ${nav.prev?'':'disabled'} title="Previous (Alt+←)">‹</button><div class="gosrch"><input id="gotoQ" placeholder="Go to ${KLABEL[k][1]}…" autocomplete="off"><div id="gotoRes" class="gores hidden"></div></div><button class="btn sm" data-act="deal-go" data-id="${nav.next||''}" ${nav.next?'':'disabled'} title="Next (Alt+→)">›</button></div><span class="mut small" style="min-width:52px;text-align:right">${nav.i>=0?(nav.i+1)+' of '+nav.n:''}</span></div><button class="addrcp" data-act="addr-copy" title="Copy address">${esc(fullAddr(tx))} <span>⧉</span></button><div id="dHead" style="margin-top:8px">${card(tx,false)}</div><div class="phbar" id="dPh">${phBar(tx)}</div>
 <div class="tabs">${TABS[k].map(([t,l])=>`<button data-act="tab" data-tab="${t}" class="${S.tab===t?'on':''}">${l}${t==='review'?rvBadge(tx):''}</button>`).join('')}</div></div><div id="tabBody">${tabBody(tx)}</div></div>`;growAll();setTimeout(()=>{if(S.tab==='summary')markSeen(tx.id);chatScroll();chatUpdate()},0)}
const rvBadge=tx=>{const n=checks(tx).filter(x=>x.lvl==='bad').length;return n?` <span class="pill over" style="font-size:11px">${n}</span>`:''};
const refreshHead=tx=>{const h=$('#dHead');if(h)h.innerHTML=card(tx,false)};
function renderTab(){const tx=getTx();const el=$('#tabBody');if(tx&&el){el.innerHTML=tabBody(tx);refreshHead(tx);$('#dPh').innerHTML=phBar(tx);growAll()}}
const grow=t=>{if(!t||t.tagName!=='TEXTAREA'||!t.dataset.f)return;t.style.height='auto';t.style.height=Math.max(t.scrollHeight+2,64)+'px'};const growAll=()=>setTimeout(()=>document.querySelectorAll('textarea[data-f]').forEach(grow),0);
function tabBody(tx){return ({terms:termsTab,dates:datesTab,checklist:ckTab,notes:notesTab,emails:emTab,summary:sumTab,review:reviewTab,people:peopleTab}[S.tab]||termsTab)(tx)}

function field(tx,[k,l,t,opts]){if(t==='day0'){const f=tx.f;return `<div class="f wide d0"><span>${l} <span class="mut small">(the day deadlines count from)</span></span><div class="row" style="gap:10px;flex-wrap:wrap"><label class="row small" style="gap:5px"><input type="radio" name="d0" data-d0="acc" ${f.day0_on?'':'checked'}> Acceptance date</label><label class="row small" style="gap:5px"><input type="radio" name="d0" data-d0="other" ${f.day0_on?'checked':''}> A different date</label>${f.day0_on?`<input type="date" data-f="day0" value="${esc(f.day0||'')}" style="width:auto"><input data-f="day0_why" value="${esc(f.day0_why||'')}" placeholder="Why (probate court confirmation, etc.)" style="flex:1;min-width:200px">`:''}</div></div>`}
 if(t==='coe'){const c=(tx.cont||[]).find(x=>x.k==='coe')||{};const byDate=!!c.date&&(c.days===''||c.days==null||c.coeMode==='date')||c.coeMode==='date';return `<div class="f wide d0"><span>${l}</span><div class="row" style="gap:10px;flex-wrap:wrap"><label class="row small" style="gap:5px"><input type="radio" name="coem" data-coem="days" ${byDate?'':'checked'}> <input data-coe="days" value="${esc(byDate?'':c.days==null?'':c.days)}" style="width:64px" ${byDate?'disabled':''}> days after Day 0</label><label class="row small" style="gap:5px"><input type="radio" name="coem" data-coem="date" ${byDate?'checked':''}> On a specific date <input type="date" data-coe="date" value="${esc(byDate?c.date||'':'')}" style="width:auto" ${byDate?'':'disabled'}></label><span class="mut small" id="coeOut">${coeOf(tx)?'Closes '+fmtS(coeOf(tx)):''}</span></div></div>`}const v=tx.f[k]==null?'':tx.f[k];const p=PKEY[k];const pa=p?` data-p="${p}"`:'';
 if(t==='sel')return `<label class="f">${l}<select data-f="${k}"${pa}>${opts.map(o=>`<option ${o===v?'selected':''}>${esc(o)}</option>`).join('')}</select></label>`;
 if(t==='member')return `<label class="f">${l}<select data-f="${k}"><option value="">Unassigned</option>${memOpts(v)}</select></label>`;
 if(t==='area')return `<label class="f wide"><span class="row between">${l}${opts?`<span class="row" style="gap:4px">${opts.map(px=>`<button type="button" class="btn sm ghost" data-act="seq-add" data-k="${k}" data-p="${px}">+ ${px}</button>`).join('')}</span>`:''}</span><textarea data-f="${k}" ${opts?'placeholder="None"':''}>${esc(v)}</textarea></label>`;
 const dl=p&&PARTY[p].name===k?` data-look="1" autocomplete="off" placeholder="Type a name, company or email to search"`:'';
 return `<label class="f">${l}<input data-f="${k}"${pa}${dl} type="${t==='date'?'date':'text'}" ${t==='money'?'inputmode="decimal" placeholder="$"':''}${k==='state'?' placeholder="CA"':''} value="${esc(v)}"></label>`}
function datalists(){return ROLES.concat(CLIENT_ROLES).map(r=>`<datalist id="dl-${r.replace(/\W/g,'')}">${S.contacts.filter(c=>c.role===r).map(c=>`<option value="${esc(c.name)}">${esc([c.company,c.email].filter(Boolean).join(' · '))}</option>`).join('')}</datalist>`).join('')}
/* structured contractual terms */
const TP=['Seller','Buyer','Listing Agent','Selling Agent'];const BRK=['Buyer Broker','Listing Broker'];
const CC=[['cc_escrow','Escrow fee'],['cc_title',"Owner's title policy"],['cc_county','County transfer tax'],['cc_city','City transfer tax'],['cc_hoa','HOA transfer fees']];
const CCO=['','Buyer','Seller','Both (50/50)','Each to pay their own','N/A'];
const moneyS=v=>{const n=num(v);return n?'$'+Number(n).toLocaleString('en-US',{maximumFractionDigits:2}):''};
function termLines(f){const L=[];(f.credits||[]).forEach(c=>{if(c.amt)L.push(`${c.from||'Seller'} to credit ${moneyS(c.amt)} to ${c.to||'Buyer'}${c.note?' ('+c.note+')':''}`)});
 (f.comm||[]).forEach(c=>{const p=String(c.pct||'').trim(),a=moneyS(c.amt);if(!p&&!a)return;const pc=p?p.replace(/%$/,'')+'%':'';L.push(`${c.payer||'Seller'} to pay ${c.to||'Buyer Broker'} commission of ${pc&&a?pc+' AND '+a+' of purchase price':pc?pc+' of purchase price':a}`)});
 const cc=CC.filter(([k])=>f[k]).map(([k,l])=>`${l.replace("Owner's title policy","Owners Title Policy")} - ${f[k]}`);if(cc.length){if(L.length)L.push('');L.push(...cc)}return L.join('\n')}
function termsBox(tx){const f=tx.f;const sel=(a,ix,k,opts)=>`<select data-tr="${a}" data-ix="${ix}" data-k="${k}" style="width:auto">${opts.map(o=>`<option ${o===(((f[a]||[])[ix]||{})[k]||opts[0])?'selected':''}>${esc(o)}</option>`).join('')}</select>`;const inp=(a,ix,k,ph,w)=>`<input data-tr="${a}" data-ix="${ix}" data-k="${k}" value="${esc(((f[a]||[])[ix]||{})[k]||'')}" placeholder="${ph}" style="width:${w}px">`;
 const cr=(f.credits||[]).map((c,ix)=>`<div class="trow">${sel('credits',ix,'from',TP)}<span>to credit</span>${inp('credits',ix,'amt','$ amount',110)}<span>to</span>${sel('credits',ix,'to',['Buyer','Seller','Listing Agent','Selling Agent'])}${inp('credits',ix,'note','note (optional)',170)}<button class="ib" data-act="tr-del" data-a="credits" data-ix="${ix}" title="Remove">✕</button></div>`).join('');
 const cm=(f.comm||[]).map((c,ix)=>`<div class="trow">${sel('comm',ix,'payer',TP)}<span>to pay</span>${sel('comm',ix,'to',BRK)}<span>commission of</span>${inp('comm',ix,'pct','%',64)}<span>AND / OR</span>${inp('comm',ix,'amt','$ flat',100)}<span class="mut small">of purchase price</span><button class="ib" data-act="tr-del" data-a="comm" data-ix="${ix}" title="Remove">✕</button></div>`).join('');
 const prev=termLines(f);
 return `<div class="tgrp"><div class="row between"><b>Credits</b><button class="btn sm ghost" data-act="tr-add" data-a="credits">+ Credit</button></div>${cr||'<div class="mut small">None</div>'}</div>
 <div class="tgrp"><div class="row between"><b>Commission</b><button class="btn sm ghost" data-act="tr-add" data-a="comm">+ Commission</button></div>${cm||'<div class="mut small">None</div>'}</div>
 <div class="tgrp"><b>Closing costs</b><div class="ccg">${CC.map(([k,l])=>`<label class="f">${l}<select data-f="${k}">${CCO.map(o=>`<option ${o===(f[k]||'')?'selected':''} value="${o}">${o||'Not set'}</option>`).join('')}</select></label>`).join('')}</div></div>
 <div class="tgrp"><b>Other terms</b><textarea data-f="special" placeholder="None" style="margin-top:6px">${esc(f.special||'')}</textarea></div>
 <div class="tgrp"><b>Shows on the summary as</b><pre class="tprev">${esc(prev)||'<span class="mut">Nothing yet</span>'}${f.special?'\n\n'+esc(f.special):''}</pre></div>`}
function termsTab(tx){const secs=kindOf(tx)==='listing'?LS_SECTIONS:TX_SECTIONS;const L=kindOf(tx)==='listing';
 return `<div class="card sec row between" style="background:#fbf6ff;border-color:#e9d7fe"><div><b>Read the ${L?'listing agreement':'contract'} and fill this in</b><div class="hint">Upload the ${L?'RLA':'RPA plus any counter offers and addenda'} as PDFs. ${window.TCD_AI||'Claude'} reads them and shows you every value to check before anything is filled in.</div></div><label class="btn pri" style="cursor:pointer">Upload PDF<input type="file" id="aiFile" accept="application/pdf" multiple hidden></label></div>`+`<div class="row end" style="margin-bottom:8px"><button class="linkbtn small" data-act="sec-all" data-v="open">Expand all</button>&nbsp;·&nbsp;<button class="linkbtn small" data-act="sec-all" data-v="close">Collapse all</button></div>`+secs.filter(s=>!s.p).map(s=>{const k=slug(s.t);const h=(LS.secHide||{})[k];return `<div class="card sec ${h?'shut':''}"><h3 class="sech" data-act="sec-tog" data-k="${k}"><span class="tg2">${h?'+':'−'}</span> ${s.t}</h3>${h?'':s.custom==='terms'?`<div id="termsBox">${termsBox(tx)}</div>`:`<div class="grid">${s.f.filter(fl=>!(s.t==='Home warranty'&&tx.f.hw_paid_by==='Waived'&&fl[0]!=='hw_paid_by')).map(fl=>field(tx,fl)).join('')}${s.t==='Home warranty'&&tx.f.hw_paid_by==='Waived'?'<p class="hint" style="align-self:end">Buyer waives the home warranty plan.</p>':''}</div>`}</div>`}).join('')+`<p class="hint">People (agents, escrow, lender, title, buyers and sellers) are on the Participants tab.</p>`}

function calcCell(tx,c){const dl=cDead(tx,c);const d=cdate(tx,c);if(c.date&&dl&&c.date!==dl)return `<span class="mut" style="text-decoration:line-through">${fmtS(dl)}</span> → <b>${fmtS(c.date)}</b> ${c.waived?'<span class="pill">Waived</span>':c.removed?'<span class="pill ok">Done</span>':due(daysTo(c.date))}`;const rl=rolled(tx,c)?` <span class="mut small" title="Lands on ${fmtS(cdateRaw(tx,c))}, moved to the next business day">moved</span>`:'';const st=c.waived?'<span class="pill">Waived</span>':c.removed?'<span class="pill ok">Done</span>':(d?due(daysTo(d)):'');return `<b>${d?fmtS(d):'-'}</b>${rl} ${st}`}
function linkCell(tx,c){if(c.k==='coe')return '';const L=cLinked(tx,c);return c.unlink?`<button class="linkbtn small" data-act="c-link" data-id="${c.id}">Link again</button>`:L.length?`<span title="Linked with ${esc(L.map(x=>x.label).join(', '))}">🔗 ${L.length}</span> <button class="linkbtn small" data-act="c-unlink" data-id="${c.id}" title="Move this one on its own">unlink</button>`:'<span class="mut">-</span>'}
function datesTab(tx){return `<div class="card">${tx.f.acceptance?'':'<p class="warn" style="margin-top:0">Enter the acceptance date on the Attributes tab to calculate these deadlines.</p>'}
 <table class="list dates cdt"><colgroup><col style="width:27%"><col style="width:12%"><col style="width:6%"><col style="width:4%"><col style="width:16%"><col style="width:13%"><col style="width:12%"><col style="width:4%"><col style="width:4%"><col style="width:2%"></colgroup><thead><tr><th>Milestone <span class="mut small">· email code</span></th><th>From</th><th>Days</th><th title="Count business days">Biz</th><th>Deadline</th><th>Moved to</th><th>Linked</th><th title="Waived">Wvd</th><th title="Done / removed">Done</th><th></th></tr></thead><tbody>
 ${tx.cont.filter(c=>c.k!=='coe').map(c=>`<tr id="cr-${c.id}" class="${c.waived||c.removed?'struck':''}"><td><input class="lbl" data-c="${c.id}" data-cf="label" value="${esc(c.label)}"><div class="ccode"><span>{{</span><input data-c="${c.id}" data-cf="k" value="${esc(c.k||'')}" placeholder="${esc(slug(c.label))}"><span>_date}}</span></div></td><td>${c.k==='coe'?'<span class="mut small">Acceptance</span>':`<select data-c="${c.id}" data-cf="from"><option value="">Acceptance</option><option value="coe" ${c.from==='coe'?'selected':''}>Before COE</option></select>`}</td><td><input data-c="${c.id}" data-cf="days" inputmode="numeric" value="${esc(c.days)}"></td><td class="c"><input type="checkbox" data-c="${c.id}" data-cf="biz" ${c.biz?'checked':''}></td><td id="cd-${c.id}" class="small">${calcCell(tx,c)}</td><td><input type="date" data-c="${c.id}" data-cf="date" value="${esc(c.date)}" title="Leave blank to use the contract deadline"></td><td class="small" id="cl-${c.id}">${linkCell(tx,c)}</td><td class="c">${c.k==='coe'?'':`<input type="checkbox" data-c="${c.id}" data-cf="waived" ${c.waived?'checked':''}>`}</td><td class="c"><input type="checkbox" data-c="${c.id}" data-cf="removed" ${c.removed?'checked':''}></td><td><button class="ib" data-act="cont-del" data-id="${c.id}" title="Remove row">✕</button></td></tr>`).join('')}
 </tbody></table><div class="row between" style="margin-top:12px"><div class="row"><button class="btn sm" data-act="cont-add">+ Add date</button><label class="row small" style="gap:5px"><input type="checkbox" id="rollChk" ${tx.f.roll==='no'?'':'checked'}> Move deadlines that land on a weekend or holiday to the next business day</label></div>${downloads?'<button class="btn sm" data-act="ics">Download calendar file (.ics)</button>':''}</div><p class="hint">Days count from acceptance, or before closing when From says so (calendar days unless Biz is checked). The deadline is what the contract says; put the new date in Moved to when a date gets extended. Dates that share the same deadline (like appraisal and loan) are linked: moving one moves the others. Every row has a template code you can use in emails: <b>{{code_date}}</b> (Nov 17, 2026), <b>{{code_short}}</b> (11/17/26) or <b>{{code_day}}</b> (Tue, Nov 17). Add your own rows (for example a rent-back or SPRP date) and give them a code.</p></div>`}

/* tasks */
function drvOpts(tx,i){const L=kindOf(tx)==='listing';
 const base=L?[['LIST','Start date'],['FIRST','First look'],['LIVE','Live date'],['EXP','Expiration'],['PHOTOS','Photos date']]:[['ACC','Acceptance (MA)']].concat((tx.cont||[]).filter(c=>c.k).map(c=>[c.k.toUpperCase(),c.label]));
 const o=base.concat([['DATE','Specific date']]).map(([v,l])=>`<option value="${v}" ${i.drv===v?'selected':''}>${esc(l)}</option>`).join('');
 const t=tx.checklist.filter(x=>x.id!==i.id).map(x=>`<option value="T:${x.id}" ${i.drv==='T:'+x.id?'selected':''}>After: ${esc(x.text.slice(0,42))}</option>`).join('');
 return o+(t?`<optgroup label="When another task is done">${t}</optgroup>`:'')}
function ckRow(tx,i){const d=itemDue(tx,i);const isDate=!i.drv||i.drv==='DATE';
 const st=i.done?`<span class="pill ok">Done ${fmtX(i.doneAt)}</span>`:(d?due(daysTo(d)):'');
 return `<div class="ck ${i.done?'done':''}" id="ck-${i.id}"><input type="checkbox" data-ck="${i.id}" data-ckf="done" ${i.done?'checked':''}>
 <input class="cktext" data-ck="${i.id}" data-ckf="text" value="${esc(i.text)}">
 <select data-ck="${i.id}" data-ckf="who">${whoOpts(i.who)}</select>
 <select data-ck="${i.id}" data-ckf="drv">${drvOpts(tx,i)}</select>
 ${isDate?`<input type="date" class="span2" data-ck="${i.id}" data-ckf="due" value="${esc(i.due||'')}">`:`<input data-ck="${i.id}" data-ckf="days" value="${esc(i.days==null?0:i.days)}" inputmode="numeric" title="Days after (use a minus sign for days before)"><span class="dd">${d?fmtS(d):'<span class="mut" style="font-weight:400">waiting</span>'}</span>`}
 <span class="st">${st} ${flagIcons(i)}</span><button class="btn ghost sm ms ${i.ms?'on':''}" data-act="ck-ms" data-id="${i.id}" title="Milestone: shows on the summary and in {{timeline}}">★</button><button class="btn ghost sm" data-act="ck-del" data-id="${i.id}" title="Delete task">✕</button></div>`}
function ckList(tx){if(S.ckView==='table')S.ckView='cards';if(S.ckView==='board')return boardHTML(rowsForTx(tx,false).filter(r=>!S.whoF||r.who===S.whoF),false);if(S.ckView==='cards')return ckCards(tx);let items=tx.checklist.filter(i=>tkPass(tx,i)&&(!S.whoF||i.who===S.whoF));
 items=items.map(i=>({i,d:i.done?(i.doneAt||''):itemDue(tx,i)})).sort((a,b)=>(a.i.done-b.i.done)||((a.d||'9')<(b.d||'9')?-1:(a.d||'9')>(b.d||'9')?1:0)).map(x=>x.i);
 return items.length?`<div class="ckhead"><span></span><span>Task</span><span>Assigned</span><span>Driver</span><span>Days</span><span>Due</span><span>Status</span><span title="Milestone">★</span><span></span></div>`+items.map(i=>ckRow(tx,i)).join(''):'<p class="mut">No tasks to show. Import a checklist above or add a task below.</p>'}
function ckTab(tx){const s=ckStats(tx);return `<div class="card"><div class="row between"><div class="row"><select id="ckTpl" style="width:auto"><option value="">Add tasks from a checklist…</option>${S.checklist.map(t=>`<option value="${t.id}">${esc(t.name)}</option>`).join('')}</select><button class="btn sm" data-act="ck-apply">Add</button><span class="hint">You can add as many checklists as you like.</span></div>
 <div class="row"><span class="seg"><button class="${S.ckView!=='board'?'on':''}" data-act="ckview" data-v="cards">List</button><button class="${S.ckView==='board'?'on':''}" data-act="ckview" data-v="board">Board</button></span><select id="ckSort" style="width:auto"><option value="">Sort by due date</option><option value="no" ${S.ckSort==='no'?'selected':''}>Sort by task #</option></select><select id="whoF" style="width:auto"><option value="">Everyone's tasks</option>${memOpts(S.whoF)}</select><span class="mut" id="ckCount">${s.p}% complete · ${s.t-s.d} to do</span></div></div>
 ${tkFilterBar()}<div class="prog"><i id="ckProg" style="width:${s.p}%"></i></div><div class="scroll"><div id="ckList" style="${S.ckView==='table'?'min-width:860px':S.ckView==='board'?'min-width:760px':''}">${ckList(tx)}</div></div>
 <div class="addrow"><input id="ckNew" placeholder="Add a task… (optional: [ACC+3], [COE-5], [#2+1], @Name)"><button class="btn sm" data-act="ck-add">Add</button></div></div>`}
function tkModal(tid,id){S._tkm={tid,id};tkModalRefresh()}
function tkModalRefresh(){let m=document.getElementById('tkMod');const st=S._tkm;const t=st&&getTx(st.tid);const i=t&&(t.checklist||[]).find(x=>x.id===st.id);
 if(!i){if(m)m.remove();S._tkm=null;return}
 if(!m){m=document.createElement('div');m.id='tkMod';m.className='tkmod';app.appendChild(m)}
 m.dataset.txctx=t.id;const d=i.done?(i.doneAt||''):itemDue(t,i);
 m.innerHTML=`<div class="tkmbox"><div class="row between" style="align-items:flex-start"><div><div class="mut small">${esc(tkAddr(t))}</div><h3 style="margin:2px 0 0">${esc(i.text||'Untitled task')}</h3><div class="row" style="gap:6px;margin-top:6px"><label class="row small" style="gap:6px"><input type="checkbox" data-tkp="${t.id}|T:${i.id}" ${i.done?'checked':''}> Done</label>${i.done?'':d?due(daysTo(d)):''}<span class="mut small">${d?fmtS(d):''}</span></div></div><button class="btn ghost sm" data-act="tkm-close" title="Close">✕</button></div>${tkEditor(t,i)}<div class="row end" style="margin-top:8px"><button class="btn sm" data-act="tkp-open" data-id="${t.id}">Open deal</button><button class="btn sm pri" data-act="tkm-close">Done editing</button></div></div>`}
function refreshCk(tx){setTimeout(tkModalRefresh,0);if(S.view==='tasks'){const a=document.activeElement;if(a&&a.dataset&&(a.dataset.ckf==='text'))return;refreshTasks();return}const l=$('#ckList');if(l)l.innerHTML=ckList(tx);const s=ckStats(tx);const p=$('#ckProg');if(p)p.style.width=s.p+'%';const c=$('#ckCount');if(c)c.textContent=s.p+'% complete · '+(s.t-s.d)+' to do';refreshHead(tx)}
/* checklist template lines <-> rows */
function parseTL(line){const r={no:'',ap:'',ms:false,who:'',drv:'',days:0,biz:false,key:false,pv:false,bm:false,em:[],text:''};
 line=String(line||'').replace(/^\s*#(\d+):\s*/,(m,n)=>{r.no=n;return ''});
 line=line.replace(/\{([BS])\}/i,(m,x)=>{r.ap=x.toUpperCase();return ''});
 line=line.replace(/<em:([^>]*)>/i,(m,x)=>{r.em=x.split(',').map(v=>v.trim()).filter(Boolean).map(v=>/^\d+$/.test(v)?'tcd-'+v.padStart(2,'0'):v);return ''});
 line=line.replace(/\{(key|priv|flag|biz)\}/gi,(m,x)=>{x=x.toLowerCase();if(x==='key')r.key=true;else if(x==='priv')r.pv=true;else if(x==='flag')r.bm=true;else r.biz=true;return ''});
 if(line.includes('★')){r.ms=true;line=line.replace(/★/g,'')}
 line=line.replace(/@(All|Anyone|[A-Za-z]+)\b/,(m,n)=>{if(/^all$/i.test(n)){r.who='*';return ''}if(/^anyone$/i.test(n)){r.who='';return ''}const mm=S.members.find(x=>x.name.toLowerCase()===n.toLowerCase());if(mm){r.who=mm.name;return ''}return m});
 const m=/^\s*\[\s*(#\d+|[a-z]+)\s*([+-]\s*\d+)?\s*\]\s*/i.exec(line);if(m){r.drv=m[1].toUpperCase();r.days=parseInt((m[2]||'0').replace(/\s/g,''),10)||0;line=line.slice(m[0].length)}
 r.text=line.replace(/\s+/g,' ').trim();return r}
function serTL(r){const d=r.drv?`[${r.drv}${r.days>=0?'+':''}${r.days||0}] `:'';return `${r.no?'#'+r.no+': ':''}${d}${r.ap?'{'+r.ap+'} ':''}${r.text}${r.who==='*'?' @All':r.who?' @'+r.who:''}${r.ms?' ★':''}${r.key?' {key}':''}${r.pv?' {priv}':''}${r.bm?' {flag}':''}${r.biz?' {biz}':''}${r.em&&r.em.length?' <em:'+r.em.join(',')+'>':''}`.replace(/\s+/g,' ').trim()}
const TL_DRV=[['MA','Acceptance (MA)'],['CLS','Before closing (CLS)'],['EMD','EMD date'],['DISC','Seller disclosures'],['INSP','Inspection'],['INS','Insurance'],['TITLE','Prelim title'],['APPR','Appraisal'],['LOAN','Loan'],['HOA','HOA docs'],['VP','Walkthrough (VP)'],['COE','Closing date'],['LIST','Listing start'],['FIRST','First look'],['LIVE','Go live'],['EXP','Expiration'],['PHOTOS','Photos'],['TODAY','Day it is added'],['','No date']];
function tlEditor(t){S.tlRows=S.tlRows&&S.tlFor===t.id?S.tlRows:(t.items||[]).map(parseTL);S.tlFor=t.id;const R=S.tlRows;const q=(S.tlQ||'').toLowerCase();
 const nos=R.map(r=>r.no).filter(Boolean);const ico=(k,on,l,tt)=>`<button class="tli ${on?'on':''}" data-act="tl-tog" data-k="${k}" title="${tt}">${l}</button>`;
 return `<input id="tlQ" placeholder="Search tasks…" value="${esc(S.tlQ||'')}" style="margin-bottom:8px"><div class="scroll"><table class="tlt"><thead><tr><th><button class="thsort" data-act="tl-sort" title="Sort by number">#&nbsp;⇅</button></th><th>Features</th><th>Description</th><th>Assigned</th><th>Driver</th><th>Days</th><th>Applies to</th><th></th></tr></thead><tbody>
 ${R.map((r,ix)=>!q||r.text.toLowerCase().includes(q)?`<tr data-tl="${ix}" class="${r.ms?'crit':''}"><td><input class="tln" data-tlf="no" value="${esc(r.no)}" placeholder="${ix+1}"></td>
 <td class="nw">${ico('ms',r.ms,'⚠','Critical / milestone')}${ico('key',r.key,'🔑','Key task')}${ico('pv',r.pv,'🙈','Private (hidden from agents)')}${ico('bm',r.bm,'⚑','Flag')}${ico('biz',r.biz,'B','Count business days')}<button class="tli em ${r.em.length?'on':''}" data-act="tl-em" title="${esc(r.em.map(id=>(S.email.find(x=>x.id===id)||{}).name||id).join(', ')||'Link emails')}">✉${r.em.length?' '+r.em.length:''}</button></td>
 <td><input data-tlf="text" value="${esc(r.text)}" style="min-width:260px;${r.ms?'font-weight:700':''}"></td>
 <td><select data-tlf="who" style="width:auto">${whoOpts(r.who)}</select></td>
 <td><select data-tlf="drv" style="width:auto">${TL_DRV.map(([v,l])=>`<option value="${v}" ${r.drv===v||(v==='MA'&&r.drv==='ACC')?'selected':''}>${l}</option>`).join('')}${nos.filter(n=>n!==r.no).map(n=>`<option value="#${n}" ${r.drv==='#'+n?'selected':''}>After task #${n}</option>`).join('')}${r.drv&&r.drv[0]==='#'&&!nos.includes(r.drv.slice(1))?`<option selected value="${esc(r.drv)}">${esc(r.drv)}</option>`:''}</select></td>
 <td><input class="tln" data-tlf="days" value="${r.drv==='CLS'?Math.abs(r.days||0):r.days||0}" title="${r.drv==='CLS'?'Days before closing':'Days after'}"></td>
 <td><select data-tlf="ap" style="width:auto"><option value="">Both</option><option value="B" ${r.ap==='B'?'selected':''}>Buyer</option><option value="S" ${r.ap==='S'?'selected':''}>Seller</option></select></td>
 <td class="nw"><button class="ib" data-act="tl-mv" data-d="-1" title="Move up">↑</button><button class="ib" data-act="tl-mv" data-d="1" title="Move down">↓</button><button class="ib" data-act="tl-del" title="Delete">🗑</button></td></tr>`:'').join('')}
 </tbody></table></div><div class="row between" style="margin-top:8px"><button class="btn sm" data-act="tl-add">+ Add task</button><button class="linkbtn small" data-act="tl-raw">Edit as text</button></div>
 <p class="hint">⚠ critical tasks tied to a critical date (EMD, Inspection, Appraisal, Loan…) follow that date when it's moved, and checking them off marks the date done. "After task #" counts from when that task is completed. ✉ links emails so they open right from the task.</p>`}
function applyTpl(tx,lines){const L=kindOf(tx)==='listing';const side=tx.f.side||'Buyer';
 const parsed=lines.filter(x=>x.trim()).map((line,idx)=>{const r=parseTL(line);const it={id:uid(),no:r.no||String(idx+1),text:r.text,who:r.who,done:false,drv:'DATE',days:r.days||0,due:'',ms:r.ms,key:r.key,bm:r.bm,biz:r.biz,em:r.em.slice()};if(r.pv)it.pub=false;it._r=r.drv;it._l=r.no||String(idx+1);it._ap=r.ap;return it});
 const keep=parsed.filter(it=>!it._ap||L||side==='Dual'||(it._ap==='B'&&side==='Buyer')||(it._ap==='S'&&side==='Seller'));
 const byL={};keep.forEach(x=>{byL[x._l]=x});
 keep.forEach(it=>{if(it._r){if(it._r[0]==='#'){const t=byL[it._r.slice(1)];if(t&&t!==it)it.drv='T:'+t.id}else if(it._r==='MA'||it._r==='ACC')it.drv=L?'LIST':'ACC';else if(it._r==='CLS'){it.drv=L?'EXP':'COE';it.days=-Math.abs(it.days)}else if(it._r==='TODAY'){it.drv='DATE';it.due=iso(addD(new Date(),it.days));it.days=0}else if(it._r==='START')it.drv='LIST';else it.drv=it._r}
  if(!L&&it.drv==='VP'){const c=(tx.cont||[]).find(x=>x.k==='vp');if(c&&(c.days===''||c.days==null)){c.days=5;c.from='coe'}}
  delete it._r;delete it._l;delete it._ap;tx.checklist.push(it)});return keep.length}

/* notes */
const NIC={"clock": "<svg viewBox=\"0 0 24 24\" width=\"14\" height=\"14\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><circle cx=\"12\" cy=\"12\" r=\"9\"/><path d=\"M12 7v5l3 2\"/></svg>", "user": "<svg viewBox=\"0 0 24 24\" width=\"14\" height=\"14\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><circle cx=\"12\" cy=\"8\" r=\"4\"/><path d=\"M4 21c0-4 4-6 8-6s8 2 8 6\"/></svg>", "doc": "<svg viewBox=\"0 0 24 24\" width=\"14\" height=\"14\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><rect x=\"5\" y=\"3\" width=\"14\" height=\"18\" rx=\"2\"/><path d=\"M9 8h6M9 12h6M9 16h4\"/></svg>"};
function noteCard(n,i,len){return `<div class="ncard ${n.pub?'pubn':''} ${n.key?'keyn':''}" draggable="${S.noteEdit===n.id?'false':'true'}" data-nid="${n.id}">
 <div class="nhead"><span class="nmeta">${NIC.clock} ${fmtWhen(n.at)}</span><span class="nmeta">${NIC.user} ${esc(n.by||'TC Team')}</span><span class="nmeta ntitle" data-act="note-edit" data-id="${n.id}" title="Edit">${NIC.doc} ${esc(n.title||'Note')}</span><span class="nsp"></span>${n.key?'<span class="nchip ck">🔑 Key</span>':''}<span class="nchip ${n.pub?'cp':'cv'}">${n.pub?'👁 Public':'Private'}</span></div>
 ${S.noteEdit===n.id?`<div class="nbody"><input id="neTitle" value="${esc(n.title||'')}" placeholder="Note name" style="margin-bottom:8px"><textarea id="neText" style="min-height:160px">${esc(n.text)}</textarea><div class="row end" style="margin-top:8px"><button class="btn sm" data-act="note-cancel">Cancel</button><button class="btn pri sm" data-act="note-save" data-id="${n.id}">Save</button></div></div>`
  :`<div class="nbody ntext" data-act="note-edit" data-id="${n.id}" title="Click to edit">${esc(n.text)||'<span class="mut">Empty note</span>'}</div>`}
 <div class="nfoot"><span class="nhandle" title="Drag to reorder">⋮⋮</span><button class="ib" data-act="note-mv" data-id="${n.id}" data-d="-1" ${i===0?'disabled':''} title="Move up">↑</button><button class="ib" data-act="note-mv" data-id="${n.id}" data-d="1" ${i===len-1?'disabled':''} title="Move down">↓</button><span class="nsp"></span>
 <button class="ib ${n.key?'on':''}" data-act="note-key" data-id="${n.id}" title="${n.key?'Key note (prints on summary when public)':'Make key note'}">🔑</button><button class="ib ${n.pub?'on':''}" data-act="note-pub" data-id="${n.id}" title="${n.pub?'Public: click to make private':'Private: click to make public'}">${n.pub?'👁':'🙈'}</button><button class="ib" data-act="note-dup" data-id="${n.id}" title="Duplicate">⧉</button><button class="ib" data-act="note-edit" data-id="${n.id}" title="Edit">✎</button><button class="ib" data-act="note-del" data-id="${n.id}" title="Delete">🗑</button></div></div>`}
function notesTab(tx){const L=tx.notes;return `<div class="card"><div class="row between" style="margin-bottom:8px;gap:8px;flex-wrap:wrap"><input id="noteTitle" placeholder="Note name (optional)" style="max-width:320px"><div class="row"><button class="btn sm" data-act="note-imp">Import templates</button>${L.length>1?`<button class="btn sm ghost" data-act="note-sort" data-d="new">Sort newest first</button><button class="btn sm ghost" data-act="note-sort" data-d="old">Oldest first</button>`:''}</div></div><textarea id="noteText" placeholder="Write a note…"></textarea>
 <div class="row between" style="margin-top:8px"><div class="row small"><label class="row" style="gap:4px"><input type="checkbox" id="notePub"> Public</label><label class="row" style="gap:4px"><input type="checkbox" id="noteKey"> Key note</label><span class="hint">Public key notes print on the summary, in the order shown here.</span></div><button class="btn pri sm" data-act="note-add">Add note</button></div></div>
 <div id="nList">${L.map((n,i)=>noteCard(n,i,L.length)).join('')||'<p class="mut" style="margin:12px 4px">No notes yet.</p>'}</div>`}

/* rich text */
const isHTML=t=>/<(br|p|div|b|strong|i|em|u|a|table|ul|ol|li|span|h\d)\b[^>]*>/i.test(String(t||''));
const toHTML=t=>isHTML(t)?String(t):esc(String(t||'')).replace(/\n/g,'<br>');
function toText(h){if(!isHTML(h))return String(h||'');const d=document.createElement('div');d.innerHTML=String(h).replace(/<br\s*\/?>/gi,'\n').replace(/<\/(p|div|li|h\d)>/gi,'\n').replace(/<\/tr>/gi,'\n').replace(/<\/t[dh]>\s*<t[dh][^>]*>/gi,' | ').replace(/<li[^>]*>/gi,'• ');
 d.querySelectorAll('a').forEach(a=>{const u=a.getAttribute('href')||'';if(u&&u!==a.textContent&&!/^mailto:/i.test(u))a.textContent=a.textContent+' ('+u+')'});return d.textContent.replace(/\u00a0/g,' ').replace(/\n{3,}/g,'\n\n').trim()}
const RTB=[['bold','<b>B</b>','Bold'],['italic','<i>I</i>','Italic'],['underline','<u>U</u>','Underline'],['link','🔗','Add link'],['unlink','⛓︎̸','Remove link'],['insertUnorderedList','•','Bullets'],['insertOrderedList','1.','Numbered list'],['table','▦','Insert table'],['row','+row','Add table row'],['col','+col','Add table column'],['delrow','−row','Delete table row'],['removeFormat','⌫','Clear formatting']];
const RTX=`<select data-rtesize title="Text size"><option value="">Size</option><option value="1">Tiny</option><option value="2">Small</option><option value="3">Normal</option><option value="4">Large</option><option value="5">Larger</option><option value="6">Huge</option></select><label class="rtcol" title="Text color">A<input type="color" data-rtecolor value="#c8102e"></label><button type="button" data-rte="img" title="Upload a picture">🖼</button><button type="button" data-rte="imgurl" title="Picture from a web address">🖼🔗</button><button type="button" data-rte="imgminus" title="Make the selected picture smaller">−img</button><button type="button" data-rte="imgplus" title="Make the selected picture bigger">+img</button>`;
const SIGX='<span class="rtsep"></span><button type="button" data-rte="lay1" title="Photo on the left, details on the right">▥ Photo left</button><button type="button" data-rte="lay2" title="Photo on top">▤ Photo top</button><button type="button" data-rte="lay3" title="Text with a divider line">▭ Simple</button>';
