function pickImage(ed){const inp=document.createElement('input');inp.type='file';inp.accept='image/*';inp.onchange=()=>{const f=inp.files[0];if(!f)return;const rd=new FileReader();rd.onload=()=>{const im=new Image();im.onload=()=>{const W=Math.min(360,im.width),H=Math.round(im.height*W/im.width);const c=document.createElement('canvas');c.width=W;c.height=H;const x=c.getContext('2d');x.fillStyle='#fff';x.fillRect(0,0,W,H);x.drawImage(im,0,0,W,H);const png=/png|gif/.test(f.type);const url=c.toDataURL(png?'image/png':'image/jpeg',.85);insImg(ed,url,Math.min(120,W))};im.src=rd.result};rd.readAsDataURL(f)};inp.click()}
