function shrinkSrc(src,maxW){return new Promise(res=>{const im=new Image();im.crossOrigin='anonymous';im.onload=()=>{try{const W=Math.min(maxW,im.naturalWidth||maxW),H=Math.round((im.naturalHeight||W)*W/(im.naturalWidth||W));const c=document.createElement('canvas');c.width=W;c.height=H;const x=c.getContext('2d');const png=/^data:image\/(png|gif)/.test(src)||/^blob:/.test(src);
  let out;if(png){x.drawImage(im,0,0,W,H);out=c.toDataURL('image/png');if(out.length>150000){x.fillStyle='#fff';x.fillRect(0,0,W,H);x.drawImage(im,0,0,W,H);out=c.toDataURL('image/jpeg',.85)}}else{x.fillStyle='#fff';x.fillRect(0,0,W,H);x.drawImage(im,0,0,W,H);out=c.toDataURL('image/jpeg',.85)}res(out.length<src.length||/^blob:/.test(src)?out:src)}catch(e){res(src)}};im.onerror=()=>res(src);im.src=src})}
