function setMarked(id,v){LS.chatUnread=LS.chatUnread||{};if(v)LS.chatUnread[id]=Date.now();else delete LS.chatUnread[id];saveLS();syncPrefs()}
const unread=id=>{const n=chatFor(id).filter(m=>m.at>seenAt(id)&&m.by!==me()).length;return n||(isMarked(id)?1:0)};
const totalUnread=()=>{const ids=new Set(S.chat.map(m=>m.txId));Object.keys(LS.chatUnread||{}).forEach(id=>ids.add(id));let n=0;ids.forEach(id=>n+=unread(id));return n};
