const TEAMCHAT='__team';const pins=()=>{const p=prefs();if(!Array.isArray(p.pins))p.pins=[];return p.pins};
const txLabel=t=>t?(t.f.address||'Untitled')+(t.f.city?', '+t.f.city:''):'Unknown property';
