 const ok=()=>{const v=inp.value.trim();if(!v){inp.focus();return}const tx0=getTx(m0.txId);if(!tx0)return;const it={id:uid(),text:v,who:md.querySelector('#ctWho').value,done:false,drv:'DATE',days:0,due:md.querySelector('#ctDue').value||'',pub:true,fromChat:m0.id};tx0.checklist.push(it);touch(tx0,1);
  m0.taskId=it.id;save('chat',m0).catch(()=>{});md.classList.add('hidden');toast('Task added to '+(tx0.f.address||'the deal'));if(S.view==='chat')pcRefresh();else if(S.view==='detail'){chatUpdate();if(S.tab==='checklist')refreshCk(tx0)}};
