function syncContact(tx,p){const P=PARTY[p];const name=String(tx.f[P.name]||'').trim();if(name.length<2)return;
 const vals={};['company','phone','email','dre'].forEach(k=>{if(P[k])vals[k]=String(tx.f[P[k]]||'').trim()});
 let c=S.contacts.find(x=>x.id===tx.f[p+'_cid']);if(c&&c.name.trim().toLowerCase()!==name.toLowerCase())c=null;if(!c)c=findContact(P.role,name);
 if(c){const nc=clone(c);let ch=false;for(const k in vals){if(vals[k]&&vals[k]!==(nc[k]||'')){nc[k]=vals[k];ch=true}}if(ch)save('contacts',nc).catch(dbErr);if(tx.f[p+'_cid']!==c.id){tx.f[p+'_cid']=c.id;touch(tx)}}
 else{const nc=Object.assign({id:uid(),name,role:P.role,createdAt:Date.now()},vals);save('contacts',nc).catch(dbErr);tx.f[p+'_cid']=nc.id;touch(tx);toast('Saved '+name+' to '+(CLIENT_ROLES.includes(P.role)?'Buyers & Sellers':'Associates'))}}
