  set('odre',o.ol,true);set('dre',o.al);set('team_email',o.te);set('fax',o.fx);if(o.st&&!c.street){c.street=o.st;c.city=c.city||o.ci||'';c.state=c.state||o.sa||'';c.zip=c.zip||o.zp||'';ch=true}
