 const upd=new Map(),add=[];L.forEach((p,i)=>{const e=String(p.email||'').toLowerCase();const c=(e&&byE[e])||byN[String(p.name).toLowerCase()];const note=p.with&&p.with.length?'On file with: '+p.with.join(' & '):'';
  if(c){const n=upd.get(c.id)||clone(c);['email','phone','address','first','last'].forEach(k=>{if(p[k]&&!n[k])n[k]=p[k]});if(note&&!String(n.notes||'').includes(note))n.notes=[n.notes,note].filter(Boolean).join('\n');upd.set(c.id,n)}
  else{const nc={id:'tdB'+String(i).padStart(4,'0'),name:p.name,first:p.first||'',last:p.last||'',role:p.role||'Buyer/Seller',email:p.email||'',phone:p.phone||'',address:p.address||'',notes:note,createdAt:1710000000000+i,source:'tcDocs'};add.push(nc);if(e)byE[e]=nc;byN[p.name.toLowerCase()]=nc}});
